const fs = require('fs');
const filePath = 'card-bg-experiment.html';
let content = fs.readFileSync(filePath, 'utf8');

const ICONS = {
  swords: 'data:image/png;base64,',
  hourglass: 'data:image/png;base64,',
  leaf: 'data:image/png;base64,',
  gems: 'data:image/png;base64,',
  flame: 'data:image/png;base64,',
};

// Quitar el CSS del marco anterior si existe (ya no lo necesitamos)
content = content.replace(/<style>\n\.stat-icon-frame[^<]*<\/style>\n?/g, '');

// Reemplazar cada icono SVG (con o sin marco) por la imagen real
const patterns = [
  { key: 'swords', re: /<div class="stat-icon-frame"><svg viewBox="0 0 24 24" width="13" height="13"><g filter="url\(#statGlow\)" fill="none" stroke="url\(#statGold\)" stroke-width="1\.8" stroke-linecap="round"><path d="M4 4l16 16M20 4L4 20"\/><\/g><\/svg><\/div>/ },
  { key: 'hourglass', re: /<div class="stat-icon-frame"><svg viewBox="0 0 24 24" width="13" height="13"><g filter="url\(#statGlow\)" fill="none" stroke="url\(#statGold\)" stroke-width="1\.6"><path d="M6 3h12M6 21h12M6 3c0 5 5 6 6 9-1 3-6 4-6 9M18 3c0 5-5 6-6 9 1 3 6 4 6 9"\/><\/g><\/svg><\/div>/ },
  { key: 'leaf', re: /<div class="stat-icon-frame"><svg viewBox="0 0 24 24" width="13" height="13"><g filter="url\(#statGlow\)"><path d="M4 20c0-9 6-16 16-16-1 10-8 16-16 16z" fill="none" stroke="url\(#statGold\)" stroke-width="1\.6"\/><\/g><\/svg><\/div>/ },
  { key: 'gems', re: /<div class="stat-icon-frame"><svg viewBox="0 0 24 24" width="13" height="13"><g filter="url\(#statGlow\)" fill="url\(#statGold\)"><circle cx="12" cy="6" r="2\.2"\/><circle cx="6" cy="14" r="2\.2"\/><circle cx="18" cy="14" r="2\.2"\/><circle cx="12" cy="19" r="1\.8"\/><\/g><\/svg><\/div>/ },
  { key: 'flame', re: /<div class="stat-icon-frame"><svg viewBox="0 0 24 24" width="13" height="13"><path filter="url\(#statGlow\)" fill="url\(#statGold\)" d="M12 2c1 4-3 5-3 9a3 3 0 0 0 6 0c0-1\.5-1-2-1-3\.5 2 1\.5 3 4 3 6\.5a5 5 0 0 1-10 0C7 9 10 6 12 2z"\/><\/svg><\/div>/ },
];

let count = 0;
patterns.forEach(p => {
  if (p.re.test(content)) {
    content = content.replace(p.re, `<img src="${ICONS[p.key]}" style="width:26px;height:26px;object-fit:contain;margin:0 auto 3px;display:block;filter:drop-shadow(0 0 4px rgba(201,168,76,0.4));">`);
    count++;
  } else {
    console.error('NO ENCONTRADO: ' + p.key);
  }
});

fs.writeFileSync(filePath, content);
console.log(count + ' de 5 iconos reemplazados por imagenes reales');
